'use strict';

/**
 * Credits for AI work that finishes after the HTTP request, e.g. A+ images generated by a
 * Google batch job and collected later by a scheduled job.
 *
 *   const hold = await holdForBackgroundJob(req, 'APLUS_CONTENT', credits); // in the request
 *   job.aiCreditHold = hold;                                                // store with the job
 *   await settleBackgroundHold(job.aiCreditHold, [{ provider, model, images: 5 }]); // job done
 *   await releaseBackgroundHold(job.aiCreditHold, 'Batch failed');          // job failed
 *
 * The hold is a separate usage-log row (deferred) so the request itself can be charged and closed
 * normally. Holds that are never settled are returned after 72 hours by the maintenance job.
 */
const crypto = require('crypto');
const service = require('./aiCredit.service');
const { write_logs } = require('../../../winston/utility/logger');

/** Credits to hold for n generated images at the current rate. */
async function imageCredits(n) {
  const settings = await service.getSettings();
  return Math.round(Math.max(0, Number(n) || 0) * settings.creditsPerImage * 100) / 100;
}

/**
 * Hold credits for background work started by this (metered) request. Returns a plain object to
 * store with the job, or null when the request isn't metered (demo user, no organization).
 * Throws AiCreditsError when the wallet can't cover it.
 * opts.provider: the AI provider the background work calls. When the organization uses its own
 * keys and has a key for it (or doesn't allow wallet fallback), nothing is held: keySource PERSONAL.
 */
async function holdForBackgroundJob(req, feature, amount, { provider = null } = {}) {
  const meter = req?.aiMeter;
  if (!meter) return null;
  const cfg = meter.keyConfig;
  const personal = Boolean(meter.personal && (!provider || cfg?.keys?.[provider] || !cfg?.allowWalletFallback));
  const hold = await service.reserve({
    organizationId: meter.organizationId,
    userId: meter.userId,
    feature,
    requestId: `${meter.organizationId}:bg:${crypto.randomUUID()}`,
    amount,
    deferred: true,
    personal,
  });
  return {
    requestId: hold.requestId,
    organizationId: String(hold.organizationId),
    walletId: String(hold.walletId),
    userId: hold.userId ? String(hold.userId) : null,
    feature,
    amount: hold.amount,
    enforced: hold.enforced,
    keySource: personal ? 'PERSONAL' : 'PLATFORM',
  };
}

/** Charge the finished background work for what it actually produced. Safe to call twice. */
async function settleBackgroundHold(hold, calls) {
  if (!hold?.requestId) return null;
  try {
    // Work done on the organization's own key is logged but not charged
    return await service.settle(hold, (calls || []).map((c) => ({ keySource: hold.keySource || 'PLATFORM', ...c })));
  } catch (err) {
    write_logs({ message: `[aiCredits] background settle failed for ${hold.requestId}: ${err.message}`, log_type: 'error' });
    return null;
  }
}

/** Return the hold without charging (the background work failed). Safe to call twice. */
async function releaseBackgroundHold(hold, reason) {
  if (!hold?.requestId) return null;
  try {
    return await service.release(hold, reason);
  } catch (err) {
    write_logs({ message: `[aiCredits] background release failed for ${hold.requestId}: ${err.message}`, log_type: 'error' });
    return null;
  }
}

/**
 * The background work won't happen after all and the request will do it itself (e.g. A+ batch
 * submission failed, images generated directly): move the hold onto the request's own hold.
 * Returns true when the request is now covered.
 */
async function moveHoldToRequest(hold, req) {
  if (!hold?.requestId) return true;
  const target = req?.aiMeter?.hold;
  if (!target) {
    await releaseBackgroundHold(hold, 'Request not metered');
    return true;
  }
  const moved = await service.transferHold(hold, target);
  return moved > 0 || !(hold.amount > 0);
}

module.exports = { imageCredits, holdForBackgroundJob, settleBackgroundHold, releaseBackgroundHold, moveHoldToRequest };
